import unittest
from finance import net_flow_report as core
from finance import net_flow_report_api as api

class OrdinaryTests(unittest.TestCase):
    def test_ordinary_0(self):
        self.assertEqual(core.net_flow(2,0),2)

    def test_ordinary_1(self):
        self.assertEqual(core.net_flow(0,0),0)

    def test_ordinary_2(self):
        self.assertEqual(api.flow_report([]),[])

    def test_ordinary_3(self):
        self.assertEqual(api.flow_report([("A",3,0)]),[("A",3)])

    def test_ordinary_4(self):
        self.assertEqual(api.flow_report([("a",0,0),("B",2,0)]),[("a",0),("B",2)])
